const input = items[0].json || {};
const message_id = String(input.message_id || '').trim();
const attachment_id = String(input.attachment_id || '').trim();
return [{ json: { ...input, message_id, attachment_id, graphUrl: `https://graph.microsoft.com/v1.0/me/messages/${encodeURIComponent(message_id)}/attachments/${encodeURIComponent(attachment_id)}` } }];

function cleanError(value) {
  if (!value) return 'Unknown error';
  if (typeof value === 'string') return value.slice(0, 600);
  if (value.message) return String(value.message).slice(0, 600);
  return JSON.stringify(value).slice(0, 600);
}
function safeText(value) {
  return String(value ?? '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
}
function person(mailbox) {
  const e = mailbox?.emailAddress || mailbox || {};
  return { name: e.name || '', email: e.address || '' };
}
function pass(response, extra = {}) {
  return [{ json: { ...extra, response, verificationStatus: 'Passed' } }];
}
function fail(tool, error, action='No Microsoft 365 state was changed.') {
  const msg = cleanError(error);
  return [{ json: { response: `Tool failed: Yes\nTool used: ${tool}\nError message: ${msg}\nAction taken: ${action}\nVerification status: Failed`, toolFailed: true, toolUsed: tool, errorMessage: msg, actionTaken: action, verificationStatus: 'Failed' } }];
}

const input = $('Prepare Graph Request').item.json;
const a = items[0].json || {};
if (a.error || !a.id) return fail('WF_ATTACHMENT_SEND_TO_TELEGRAM', a.error || a.message || 'Attachment metadata not found');
const size = Number(a.size || 0);
let note = 'Attachment metadata confirmed. Configure the Telegram sendDocument binary step after import to send the real file.';
if (size > 49 * 1024 * 1024) note = 'The file is too large for Telegram. Save it to OneDrive and share the OneDrive link instead.';
return pass(`Attachment found.\nName: ${a.name || input.file_name || ''}\nContent type: ${a.contentType || 'unknown'}\nSize: ${size} bytes\nTelegram document sending: ${size <= 49 * 1024 * 1024 ? 'Prepared, requires binary node credential selection' : 'Skipped, too large'}\nAction taken: ${note}\nVerification status: Passed`, { message_id: input.message_id, attachment_id: input.attachment_id, attachment: a, telegramChatId: input.telegramChatId });
